export const TOOL_DESCRIPTIONS: Readonly<Record<ToolName, string>> = {
  handoff_to_user:
    'Hands a human step to the user through the local overlay and waits until the user finishes it or needs you. Use it when a step must be done by a person: credentials, OAuth apps, DNS, IAM, billing, confirmations, OS or application settings.\nBefore writing a spec, call `handoff_runbooks(where, goal)` and start from a matching runbook if one exists.\nThree ways to call it. (1) Open: `{ "spec": {...}, "request_id"?: "hf_…", "ignore_runbook"?: true }`, where `spec` follows handoff-spec v1: `spec_version` 1, `goal`, `where`, optional `url` (http, https, ms-settings:, x-apple.systempreferences: only), `why_human`, `values` (name → string or list; every value the user must type or paste, taken from the project), optional `secrets` (variable name → destination file, for values the user copies from the dashboard; never their values), `steps` (objects `{ text, url?, values?, warning? }`, shown one at a time), optional `verify`, optional `lang`. (2) Continue: `{ "handoff_id", "reply", "replacement_steps"? }` to answer a question or a screenshot on the current step; `replacement_steps` replaces the remaining steps. (3) Resume: `{ "resume": "hf_…" }` to re-attach after an interrupted call, from any session; a resume of a finished handoff returns its outcome again with `already_delivered: true`.\nThe call blocks while the user works and returns an outcome JSON with `status`, `final` and `instruction`. Follow `instruction`. `in_progress` means call again with `resume` at once. `deferred` means continue other work and call `resume` before you finish your turn. `parked` means the user will resume it; mention the id in your final summary. `awaiting_verification` means run the verification yourself and report it with `handoff_verify`.\nRules. Never read the values listed in `secrets`; verify only their presence or their effect. Do not open a second handoff for the same goal; continue the same one. If a call fails because the server was disconnected, reconnect the server (for example `/mcp reconnect handoff`) and call `resume` with the same id. If the overlay app is not running the result is `status: text_mode`: present the spec in chat, guide the user step by step and collect the result in chat; in that mode nothing is logged and no verified state exists.\nErrors come back as `{ "error": { "code", "message", "problems": [{ "path", "problem", "fix" }] } }`; fix the named field and call again.',
  handoff_verify:
    'Reports the result of the verification you performed after the user finished a handoff. `ok: true` if the check passed, `false` if it failed, `null` if you could not verify; `detail` says exactly what you ran and what you observed, or why you could not verify. Never invent a result: `null` with an honest reason is recorded as "not verified", which is better than a false pass. Never read values listed in the spec\'s `secrets`; check presence or effect only. On `false` you may correct the handoff by calling `handoff_to_user` with the same `handoff_id` and `replacement_steps` that start from the actual error. A late report for a handoff that timed out is accepted.',
  handoff_runbooks:
    "Searches the user's saved runbooks in `~/.handoff/runbooks/` for a previous verified execution of the same kind of step: same `where` (normalised) and shared words in `goal`. Call it before writing a handoff spec. Each result carries `trust` (verified or confirmed_by_user), `last_verified_at` so you can weigh freshness, `last_run_failed_at`, the executed steps with their annotations, a `draft_spec` and `values_to_fill`. Fill the values from the current project and pass the completed spec to `handoff_to_user` with `ignore_runbook: true`.",
};

